import{_ as l,l as r,o as e,c as o,v as t,p as s,x as n,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"流动性溢价与栖息地","description":"","frontmatter":{"title":"流动性溢价与栖息地","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/liquidity-habitat-term.md","filePath":"econ/liquidity-habitat-term.md","lastUpdated":1789023840000}'),c={name:"econ/liquidity-habitat-term.md"};function h(u,a,m,_,A,B){const i=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="流动性溢价与栖息地" tabindex="-1">流动性溢价与栖息地 <a class="header-anchor" href="#流动性溢价与栖息地" aria-label="Permalink to &quot;流动性溢价与栖息地&quot;">​</a></h1><div class="epigraph"><p>长期利率不必等于预期短期的平均：出借人偏爱较近的到期，借款人偏爱较远的到期，缺口由期限溢价填上；客户群还可以钉住自己的栖息地。</p><footer>—— Hicks, Value and Capital, 1939；Culbertson, QJE 1957；Modigliani and Sutch, AER 1966</footer></div><p><a href="/econ/eh-term-structure">上一课</a>把纯预期假说写成滚动与锁定的无套利会计，并标明期限溢价来自 \\(m\\) 与债券回报的协方差。本课缺口是：<strong>溢价从哪一类偏好与分割里来</strong>，以及为何不同到期不能被当成完全替代品。这仍是收益率曲线上的均衡语言，不是国债的盘口、特殊券或限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯 EH 要求投资者在到期之间自由滚动，只关心期望短期路径。Hicks（1939）立刻拒绝这条完全替代：长期债券价格对利率更敏感，风险厌恶的出借人更愿意停在短端；厂商与政府却常要锁长端融资。若两边的栖息地错开，远期可以系统高于预期即期——流动性溢价。Culbertson（1957）把错开写得更硬：各到期是分割市场，供给在哪一段，哪一段的收益率就被当地的供需决定，平均关系可以断。</p><p>Modigliani 与 Sutch（1966）折中为<strong>偏好栖息地</strong>：投资者有喜欢的到期，但可以被溢价诱出栖息地，替代不完全而不是完全没有。缺口是把这三句钉成对 EH 的均衡补丁，而不是把国债微观结构提前写进本栏。</p><p><span class="marginnote">Hicks 的「流动性」是价格风险（久期），不是买卖价差。Culbertson 的分割是客户群与供给按到期错开。不要把 on-the-run、可交割最便宜、回购特殊券读进 1939/1957。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 EH 的会计上加一项随到期而变的溢价。对数线性后仍可写</p> \\[y_{nt}=\\frac{1}{n}\\sum_{k=0}^{n-1}\\mathrm{E}_t[y_{1,t+k}]+\\ell^{(n)}_t, \\]<p>纯 EH 是 \\(\\ell^{(n)}=0\\)；Hicks 式流动性偏好使 \\(\\ell^{(n)}\\) 随 \\(n\\) 上升且通常为正；分割假说允许 \\(\\ell^{(n)}\\) 随该段供需符号翻转；栖息地则说 \\(\\ell^{(n)}\\) 是把边缘投资者从偏好到期拉开的补偿，可随相对供给移动。</p><p>SDF 语言没有换：\\(\\ell^{(n)}\\) 仍是债券超额与 \\(m\\) 的协方差。本课补的是<strong>为什么</strong>协方差可以按到期排列，而不是再推一遍 \\(P_n=\\mathrm{E}[m^{(n)}]\\)。</p>',12)),(e(),s(p,null,{default:n(()=>[d(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20EH%5B%22%E7%BA%AF%20EH%3A%20%E5%AE%8C%E5%85%A8%E6%9B%BF%E4%BB%A3%22%5D%20--%3E%20GAP%5B%22%E4%BB%B7%E6%A0%BC%E9%A3%8E%E9%99%A9%E4%B8%8E%E5%AE%A2%E6%88%B7%E7%BE%A4%22%5D%0A%20%20HICKS%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20TP%5B%22%E6%9C%9F%E9%99%90%E6%BA%A2%E4%BB%B7%20%E2%84%93%22%5D%0A%20%20SEG%5B%22%E5%88%86%E5%89%B2%20%2F%20%E6%A0%96%E6%81%AF%E5%9C%B0%22%5D%20--%3E%20TP%0A%20%20TP%20--%3E%20CURVE%5B%22%E6%94%B6%E7%9B%8A%E7%8E%87%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20EH%20--%3E%20CURVE%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>政策含义在均衡层：扭转操作、期限供给若能改变相对栖息地，就可以移动 \\(\\ell^{(n)}\\) 而不必改变短端路径。这是后课非常规政策要动的那一块，本课只标明渠道，不估计溢价序列。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是不完全替代。若所有人只按期望滚动，任意到期的超额供给会被套利抹平到 EH。一旦有人把某段到期当消费或监管约束（保险负债、银行账簿、养老的久期匹配），他们成为该段的边际定价者；要把他们拉到别段，必须付溢价。Hicks 强调的是出借人的价格风险；栖息地强调的是负债结构。两者都让「向上倾斜 ⇒ 市场预期加息」这句话不可靠：倾斜里可以全是 \\(\\ell\\)。</p><p><a href="/econ/emh">有效市场</a>在这里仍只约束可预测成分必须被记成风险或栖息地补偿，而不是免费的利率投机。可预测不否证有效，只否证 \\(\\ell=0\\) 的那一版 EH。</p><h3 id="栖息地不是盘口厚度" tabindex="-1">栖息地不是盘口厚度 <a class="header-anchor" href="#栖息地不是盘口厚度" aria-label="Permalink to &quot;栖息地不是盘口厚度&quot;">​</a></h3><p>国债「谁在哪一段买」可以讲养老、保险、外国官方——这是宏观客户群，仍是均衡栖息地。盘口上某一档的挂单量、on-the-run 价差、拍卖后的 when-issued，是量化栏的协议与特殊券，本课不写。不要把 Modigliani–Sutch 的供给效应翻译成限价簿深度。</p><p><span class="marginnote">CIR（1981）已警告：到期收益率、持有期回报、远期，在 Jensen 不等式下不是同一句 EH。栖息地补丁加在哪一种写法上，必须声明；本课沿用上一课的会计版本：远期 = 风险中性期望即期。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在本栏做 Fama–Bliss 或宣布「栖息地被证实」——超额持有期回报对远期–即期利差的回归是债券实证。也不要把流动性溢价写成买卖价差的加总：Hicks 的词先于微观结构文献。非常规政策扭 \\(\\ell^{(n)}\\) 属于<a href="/econ/zlb-unconventional">零下限</a>，本课只留下相对供给这一通道。</p><p>下一课是金融栏收束：<a href="/econ/to-limit-order-book">到限价簿</a>。曲线上的 \\(y_n\\) 与 \\(\\ell^{(n)}\\) 仍是理论价格；交易所里的成交是簿事件。</p><p>倒挂可以是预期短利率下降，也可以是长端栖息地溢价骤降。不要用「倒挂预示衰退」代替假说。偏好栖息地扭曲的是平均关系，不是某一档的时间优先。</p><p>纯 EH 是完全替代。Hicks 加价格风险。Culbertson 让各段供需局部决定。Modigliani–Sutch 让溢价把人从栖息地拉出。三句都停在均衡，不进入撮合引擎。</p><p>不要把「流动性溢价」翻译成买卖价差加总后再塞进 \\(y_n\\)。价差是协议成本，在量化栏；本课的 \\(\\ell^{(n)}\\) 是对利率风险与不完全替代的补偿。下一课才承认：连 \\(y_n\\) 都还没有交易程序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EH 之后：期限溢价来自价格风险与不完全替代，不必是「长期更不流动」的同义反复。</li><li>Hicks 流动性偏好、Culbertson 分割、Modigliani–Sutch 栖息地，是对 \\(\\ell^{(n)}\\) 的三种均衡语言。</li><li>相对供给可以移动溢价；这不是国债微观结构，也不是限价簿。</li><li>出处：Hicks, <em>Value and Capital</em>；Culbertson, <em>QJE</em> 1957；Modigliani and Sutch, <em>AER</em> 1966。</li></ul>',15))])}const k=l(c,[["render",h]]);export{f as __pageData,k as default};
